const CACHE='sams-canvas-v33';
const ASSETS=['./','./index.html','./style.css?v=21','./editor.js?v=21','./gestures.js?v=20','./app.js?v=26','./collaboration-model.js?v=3','./ink-geometry.js?v=1','./ink-tools.js?v=2','./live-canvas.js?v=2','./collaboration.js?v=9','./collaboration.css?v=6','./vendor/supabase-realtime.js?v=1','./updater.js?v=4','./tutorial.js?v=1','./tutorial-integration.js?v=1','./tutorial.css?v=1','./content.js?v=22','./view-session.js?v=20','./welcome.js?v=20','./calendar.js?v=20','./projects.js?v=20','./canvas-tools.js?v=20','./studio.js?v=21','./studio.css?v=23','./knife-cursor.svg','./pen-cursor.svg','./audio/birds.ogg','./audio/wind.ogg','./audio/stream.ogg','./audio/rain.ogg','./icon.svg','./icon-192.png','./icon-256.png','./icon-512.png','./logo.png','./manifest.webmanifest','./cozy-world.svg','./cloud-config.json'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));self.skipWaiting()});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim()});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
